head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#fff6df" value="#fff6df"/><Variable name="page.text" description="Text color" type="color" default="#4c3227" value="#4c3227"/><Variable name="theme.accent" description="Accent color" type="color" default="#b74528" value="#b74528"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Fraunces', Georgia, serif;--body:Arial, sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
a{color:inherit}a:focus-visible,summary:focus-visible{outline:3px solid currentColor;outline-offset:5px}img{max-width:100%;height:auto}svg{display:block;width:100%;height:auto} .post-title a{text-decoration:none}.post-meta{font-size:.75rem;text-transform:uppercase;letter-spacing:.12em}.post-excerpt{line-height:1.7}.post-media{overflow:hidden}.post-card{min-width:0}.post-card a:hover{text-decoration:underline}.post-card:hover .post-media{filter:saturate(1.15)}.post-media img{transition:transform .4s}.post-card:hover .post-media img{transform:scale(1.035)}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}body{margin:0;background:#fff6df;color:#4c3227;font-family:Arial,sans-serif}.sun-nav{display:flex;justify-content:space-between;align-items:center;padding:27px 5%;border-bottom:1px solid #d3b58b}.sun-nav .brand{font:italic bold 37px 'Fraunces', Georgia,serif;color:#b74528;letter-spacing:-2px;text-decoration:none}.sun-nav nav{display:flex;gap:28px;font-size:12px}.sun-nav nav a{text-decoration:none}.sun-strip{text-align:center;font-size:10px;font-weight:bold;letter-spacing:.19em;background:#36543c;color:#fff6df;padding:14px}.sun-table{display:grid;grid-template-columns:1fr 1.05fr;gap:65px;padding:65px 5% 60px;align-items:center}.sun-eyebrow{font-size:9px;letter-spacing:.18em;font-weight:bold}.sun-copy h1{font:normal clamp(55px,7.2vw,100px)/.97 'Fraunces', Georgia,serif;letter-spacing:-.06em;margin:28px 0;color:#b74528}.sun-copy h1 em{font-weight:normal}.sun-copy>p{font:18px/1.6 'Fraunces', Georgia,serif;max-width:330px}.sun-copy>a{font-size:10px;letter-spacing:.09em;font-weight:bold;display:inline-block;margin-top:16px;text-underline-offset:6px}.sun-note{font:italic 16px/1.6 'Fraunces', Georgia,serif;transform:rotate(-6deg);background:#eddca8;padding:20px 25px;width:max-content;margin:35px 0 0 100px;box-shadow:4px 4px 0 #d1b473;border-radius:2px}.sun-note strong{color:#b74528}.sun-plate svg{border-radius:48% 48% 5px 5px;box-shadow:12px 12px 0 #ebd5ad;transform:rotate(2deg)}.sun-caption{font-size:8px;letter-spacing:.08em;display:block;text-align:center;margin:28px 0}.sun-pantry{background:#e2e8cb;padding:40px 5%;display:grid;grid-template-columns:1.3fr repeat(3,1fr);gap:25px;border-top:1px solid #a9b491;border-bottom:1px solid #a9b491}.sun-pantry h2{font:normal 33px/1.1 'Fraunces', Georgia,serif;margin:15px 0}.sun-pantry>a{text-align:center;text-decoration:none;border-left:1px solid #a9b491;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;transition:transform .2s}.sun-pantry>a:hover{transform:translateY(-5px)}.sun-pantry>a>span{font:56px 'Fraunces', Georgia,serif;color:#b74528;line-height:1}.sun-pantry strong{font:18px 'Fraunces', Georgia,serif}.sun-pantry small{font-size:8px;letter-spacing:.09em}.section-heading{font:normal 43px 'Fraunces', Georgia,serif;text-align:center;margin:55px 20px 30px;letter-spacing:-1px;color:#b74528}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;padding:0 5% 60px}.post-card{background:#fffaf0;padding:13px 13px 22px;border:1px solid #dec7a3}.post-media{aspect-ratio:1.2;background:#eabb74;border-radius:48% 48% 0 0;margin-bottom:18px}.post-meta{color:#925030;font-size:9px}.post-title{font:normal 25px/1.15 'Fraunces', Georgia,serif;letter-spacing:-.5px}.post-excerpt{font-size:12px}.sun-letter{padding:40px 5% 60px;background:repeating-linear-gradient(90deg,#f1d6ae 0 30px,#fff0d4 30px 60px)}.sun-letter-border{background:#fff6df;border:2px solid #b74528;outline:1px solid #b74528;outline-offset:-8px;max-width:700px;margin:auto;text-align:center;padding:42px 20px}.sun-letter-border>span{font-size:9px;letter-spacing:.15em}.sun-letter h2{font:italic normal 50px/1.06 'Fraunces', Georgia,serif;color:#b74528;margin:25px 0;letter-spacing:-2px}.sun-letter p{font:16px/1.8 'Fraunces', Georgia,serif}.sun-letter a{font-size:9px;letter-spacing:.1em}.sun-footer{padding:35px 5%;display:flex;align-items:center;justify-content:space-between;gap:20px}.sun-footer strong{font:italic bold 28px 'Fraunces', Georgia,serif;color:#b74528}.sun-footer span{font-size:10px;line-height:1.7}.sun-footer span:last-child{letter-spacing:.1em}@media(max-width:700px){.sun-nav{padding:22px 5%}.sun-nav .brand{font-size:26px}.sun-nav nav{font-size:9px;gap:12px}.sun-table{grid-template-columns:1fr;padding-top:40px;gap:25px}.sun-copy h1{font-size:75px}.sun-note{margin-left:140px;margin-top:-20px;font-size:13px}.sun-pantry{grid-template-columns:1fr 1fr;gap:30px}.sun-pantry>a{border:0}.posts-grid{grid-template-columns:1fr}.section-heading{font-size:34px}.sun-letter h2{font-size:40px}.sun-footer{flex-wrap:wrap}} .latest{max-width:none;margin:0;padding:0}
@media(max-width:400px){.sun-table{grid-template-columns:minmax(0,1fr)}.sun-copy{min-width:0}.sun-note{margin-left:auto;margin-right:14px}.sun-nav{flex-wrap:wrap;gap:15px}}
h1,h2,h3{font-family:'Fraunces', Georgia, serif}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
